from fnmatch import *
for x in range(1018, 10**9, 1018):
    if fnmatch(str(x), '*18??18'):
        if x % 18 == 0:
            divisors = set()
            for j in range(1, int(x**0.5)+1):
                if x % j == 0:
                    divisors.add(j)
                    divisors.add(x // j)
            print(x, len(divisors))
